head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

// ********************************************************************
// [WebSquare 전환 추가] 원본 소스와 비교 필요
// 
// ********************************************************************

scwin.gIsurCd;
scwin.gSeq;
scwin.gDepCd;
scwin.gEmpNo;
scwin.vScrenID = 'ULDSTF39001.xml';X < !정보--;
셋팅-- > function() {
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    scwin.gSeq = $c.frame.path("../").scwin.gSeq;
} < !정보--;
데이타;
읽어오기-- > function() {
    var url = "/OutDir.do?method=readOutDirInfo" + "&inputMessageId=OUTDIRINFO_INOUT" + "&outputMessageId=OUTDIRINFO_INOUT" + "&ISUR_CD=" + scwin.gIsurCd + "&SEQ=" + scwin.gSeq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    dts_outdir_info.DataID = encodeURI(url);
    dts_outdir_info.reset();
};
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};



// 사외이사 정보 수정
scwin.fn_Update = function() {
    //if(getObjectValue(edt_encryp_birthdd) != "" || getObjectValue(edt_encryp_birthdd).indexOf(" ") != "" ) {
    if ($c.stf.getObjectValue(edt_encryp_birthdd) != "") {
        if (Number($c.stf.getObjectValue(edt_encryp_birthdd)) > $c.ut.cGetToday("yyyymmdd").substring(0, 4)) {
            $c.win.alert("현재 연도보다 출생 연도가 큽니다.");
            edt_encryp_birthdd.focus();
            return;
        }
        if ($c.stf.getObjectValue(edt_encryp_birthdd).length < 4) {
            $c.win.alert("출생연도는 4자리 입니다.");
            edt_encryp_birthdd.focus();
            return;
        }
    }
    dts_outdir.insertRow();
    dts_outdir.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_outdir.setCellData(1, "SEQ", scwin.gSeq);
    dts_outdir.setCellData(1, "OUTDIR_NM", $c.stf.getObjectValue(txb_outdir_nm));
    dts_outdir.setCellData(1, "ENCRYP_BIRTHDD", $c.stf.getObjectValue(edt_encryp_birthdd));
    var vAnswer = confirm('저장 하시겠습니까?');
    if (vAnswer == true) {
        trs_outdir_info.Action = "/OutDir.do?method=modifyOutDirInfo&inputMessageId=OUTDIRINFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_outdir_info.KeyName = "toinb_dataid4";
        trs_outdir_info.KeyValue = "JSP(I:pInput=dts_outdir)";
        trs_outdir_info.Post();
    }
};




// 사외이사 정보 삭제
scwin.fn_Delete = function() {
    var rtn = confirm('삭제 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_outdir.insertRow();
        dts_outdir.setCellData(1, "ISUR_CD", scwin.gIsurCd);
        dts_outdir.setCellData(1, "SEQ", scwin.gSeq);
        trs_outdir_info.Action = "/OutDir.do?method=removeOutdirInfo&inputMessageId=OUTDIRINFO_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_outdir_info.KeyName = "toinb_dataid4";
        trs_outdir_info.KeyValue = "JSP(I:pInput=dts_outdir)";
        trs_outdir_info.Post();
    }
};
scwin.fn_chkBtn = function() {
    var mktId = js_market;
    // 다른 시장의 데이터는 삭제, 수정 불가	
    if (js_market != '9') {
        if (txb_ld_mkt_tp_cd.getValue() != mktId) {
            $c.stf.showObj(btn_Delete, false);
            $c.stf.showObj(btn_Save, false);
        }
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Update();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.dts_outdir_info_OnLoadError = function() {
    $c.stf.alert_error(dts_outdir_info);
};
scwin.dts_outdir_info_OnLoadCompleted = function(rowcount) {
    scwin.fn_chkBtn();
};
scwin.trs_outdir_info_OnSuccess = async function() {
    $c.win.alert("성공적으로 처리 되었습니다.");
    //self.close();
    await $c.frame.CloseFrame();
    // 부모창 reload 처리해야함	
    $c.frame.path("../").fn_Search();
};
scwin.trs_outdir_info_OnFail = function() {
    $c.win.alert('trs_outdir_info.OnFail() :' + trs_outdir_info.ErrorMsg);
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    fn_GetParentValue();

    // 가우스헤더 셋팅
    dts_outdir_info.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=OUTDIRINFO_INOUT";
    dts_outdir_info.reset();
    // 가우스헤더 셋팅
    dts_outdir.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=OUTDIRINFO_INOUT";
    dts_outdir.reset();

    //  정보 읽어오기
    fn_ReadInfo();
    $c.stf.showObj(txb_ld_mkt_tp_cd, false);
};
